python3 -c "
import re, glob, yaml, os

repos = ['lumen', 'prism', 'michi', 'monokl', 'oxc-react-codegen', 'callisto']
base = os.path.expanduser('~/Projects')
for repo in repos:
    for f in glob.glob(f'{base}/{repo}/.github/ISSUE_TEMPLATE/*'):
        if f.endswith('.yml') or f.endswith('.md'):
            content = open(f).read()
            if f.endswith('.yml'):
                try:
                    yaml.safe_load(content)
                    print(f'{repo}: {os.path.basename(f)} OK (yaml)')
                except Exception as e:
                    print(f'{repo}: {os.path.basename(f)} YAML ERROR {e}')
            else:
                m = re.match(r'^---\n(.*?)\n---\n', content, re.DOTALL)
                if not m:
                    print(f'{repo}: {os.path.basename(f)} NO FRONTMATTER')
                    continue
                try:
                    yaml.safe_load(m.group(1))
                    print(f'{repo}: {os.path.basename(f)} OK')
                except Exception as e:
                    print(f'{repo}: {os.path.basename(f)} ERROR {e}')
"

